using System;
using System.Collections;
using System.IO;
using System.Reflection;
using UnityEngine;
namespace LostRealms {
 public static class ExpansionStage5Checks {
  static readonly BindingFlags Private=BindingFlags.Instance|BindingFlags.NonPublic;
  static void Defeat(Enemy enemy){if(!enemy||enemy.Health<=0)return;enemy.Hit(100000,-1,false,Vector3.zero,true);if(enemy.Health>0)enemy.Hit(100000,-1,false,Vector3.zero,true);}
  static void Capture(Vector3 center,string name,float size=11){var go=new GameObject("Astral review camera");var camera=go.AddComponent<Camera>();camera.orthographic=true;camera.orthographicSize=size;camera.farClipPlane=200;camera.transform.position=center+new Vector3(13,16,-15);camera.transform.LookAt(center+Vector3.up);var rt=new RenderTexture(1200,800,24);camera.targetTexture=rt;var prior=RenderTexture.active;camera.Render();RenderTexture.active=rt;var image=new Texture2D(1200,800,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1200,800),0,0);image.Apply();string folder=RuntimeEvidence.Folder(5);Directory.CreateDirectory(folder);File.WriteAllBytes(Path.Combine(folder,name+".png"),image.EncodeToPNG());RenderTexture.active=prior;camera.targetTexture=null;rt.Release();UnityEngine.Object.Destroy(rt);UnityEngine.Object.Destroy(image);UnityEngine.Object.Destroy(go);}
  static Bounds Pose(Enemy enemy){var skin=enemy.Visual.GetComponentInChildren<SkinnedMeshRenderer>();var mesh=new Mesh();skin.BakeMesh(mesh,false);var points=mesh.vertices;var bounds=new Bounds(skin.transform.TransformPoint(points[0]),Vector3.zero);foreach(var p in points)bounds.Encapsulate(skin.transform.TransformPoint(p));UnityEngine.Object.Destroy(mesh);return bounds;}
  public static IEnumerator Run(Action<bool,string> check,Action<Vector2> move,Action jump){
   var g=RealmGame.I;string saved=JsonUtility.ToJson(g.Save);bool prototype=Array.IndexOf(Environment.GetCommandLineArgs(),"-astralPrototype")>=0;
   var old=new Progress{stars=new int[20],best=new float[20],unlocked=20,coins=901,gems=31,equippedWeapon=47};old.stars[19]=3;old.best[19]=155;old.relics.Add(7);old.achievements.Add("storm_guardian");Campaign.Normalize(old);Codex.Normalize(old);
   check(old.stars.Length==25&&old.best.Length==25&&old.unlocked==21&&old.stars[19]==3&&old.best[19]==155,"Stormveil saves unlock Astral without losing earlier scores");check(old.coins==901&&old.gems==31&&old.equippedWeapon==47&&old.relics.Contains(7)&&old.achievements.Contains("storm_guardian"),"Astral migration preserves inventory and reward claims");Campaign.Normalize(old);check(old.unlocked==21&&old.stars[24]==0,"Astral migration is idempotent");check(Campaign.Chapters==25&&Campaign.Stars==75&&RealmGame.Titles.Length==25&&RealmGame.Realms.Length==6&&Codex.Kinds==32&&Codex.All.Length==34,"Expanded campaign registries agree");
   g.Save=new Progress{unlocked=25,healthRank=3};Campaign.Normalize(g.Save);var reviewed=new System.Collections.Generic.HashSet<int>();
   for(int chapter=Array.IndexOf(Environment.GetCommandLineArgs(),"-astralBossFocused")>=0?25:21;chapter<=25;chapter++){
    g.LoadLevel(chapter);yield return new WaitForSeconds(.6f);check(g.Realm==5&&g.Astral&&g.World.IsBoss==(chapter==25),"Astral chapter mapping "+chapter);check(g.Player.Grounded&&!g.GateOpen(),"Astral spawn is supported and objectives seal the gate: "+chapter);
    for(int i=1;i<g.World.Route.Count;i++)check(Vector3.Distance(g.World.Route[i],g.World.Route[i-1])>=(chapter==25&&i==g.World.Route.Count-1?19f:10f),"Celestial terraces do not overlap their neighboring decks: "+chapter+" / "+i);
    foreach(var enemy in g.Enemies){check(enemy.Kind>=0&&enemy.Kind<Codex.Kinds&&enemy.Grounded&&enemy.Visual&&!enemy.Visual.UsesFallback&&(enemy.Visual.animator||enemy.GetComponent<SkeletonLimbMotion>()||enemy.GetComponent<SpiderLimbMotion>()),"Astral enemy has an animated grounded collision body: "+enemy.Kind);enemy.enabled=false;bool clear=true;float radius=enemy.Controller.radius-.03f;var low=enemy.transform.position+Vector3.up*(radius+.07f);var high=enemy.transform.position+Vector3.up*(enemy.Controller.height-radius);foreach(var collider in Physics.OverlapCapsule(low,high,radius,~0,QueryTriggerInteraction.Ignore)){for(var ancestor=collider.transform;ancestor&&ancestor!=g.World.transform;ancestor=ancestor.parent)if(ancestor.name.StartsWith("Prop Astral "))clear=false;}check(clear,"Astral enemy body starts clear of solid temple props: "+chapter+" / "+enemy.Kind);}
    foreach(var enemy in g.Enemies)if(enemy.Kind>=29&&reviewed.Add(enemy.Kind)){
     check(Resources.Load<Texture2D>("Characters/Textures/"+new[]{"AstralSentinel","StarOracle","FractureKeeper"}[enemy.Kind-29]+"_basecolor"),"Astral mesh has a supplied texture: "+enemy.Kind);
     foreach(string state in new[]{"idle","walk","attack","cast","gethit","death"}){enemy.Visual.Restart(state);yield return new WaitForSeconds(.3f);var b=Pose(enemy);float h=enemy.Boss?3.6f:enemy.Kind==30?2.1f:1.9f;check(b.size.y>h*.15f&&b.size.y<h*1.8f&&Vector3.Distance(b.center,enemy.transform.position)<h*1.8f&&Mathf.Abs(b.min.y-enemy.transform.position.y)<.25f,"Astral geometry remains visible at its body and deck: "+enemy.Kind+" / "+state);}
     enemy.Visual.Restart("walk");var bones=enemy.Visual.GetComponentsInChildren<Transform>();var rotations=new Quaternion[bones.Length];for(int i=0;i<bones.Length;i++)rotations[i]=bones[i].localRotation;yield return new WaitForSeconds(.3f);float motion=0;for(int i=0;i<bones.Length;i++)motion+=Quaternion.Angle(rotations[i],bones[i].localRotation);check(motion>1,"Astral walk animates actual bones: "+enemy.Kind);Capture(enemy.transform.position,"enemy-"+enemy.Kind,4.5f);enemy.Visual.Restart("idle");
    }
    if(chapter==21)yield return ExplorationChecks.Cross(g.World.Exploration.Crossings[0],check,move,jump,"Astral revised route");
    foreach(var route in g.Astral.Mechanisms){check(!route.Attune(route.Side),"Living court guards block focus attunement");g.Player.Warp(route.Bridge.position+Vector3.up*.03f);check(!route.RequestShift(1-route.Side),"Occupied route refuses to move under Aster");}
    if(chapter==21){var oracle=g.Enemies.Find(e=>e&&e.Kind==30);g.Player.Warp(oracle.transform.position+Vector3.back*2.5f);typeof(Enemy).GetField("timer",Private).SetValue(oracle,2f);oracle.enabled=true;var before=oracle.transform.position;yield return new WaitForSeconds(1);check((oracle.transform.position-before).sqrMagnitude>.02f&&oracle.Grounded,"Oracle retreats using its physical collision body");oracle.enabled=false;}
    if(chapter==23){var court=g.Astral.Mechanisms[0].Courts[0];var oracle=g.Enemies.Find(e=>e&&e.Kind==30&&Vector3.Distance(e.transform.position,court.position)<4);var sentinel=g.Enemies.Find(e=>e&&e.Kind==29&&Vector3.Distance(e.transform.position,court.position)<4);check(oracle&&sentinel,"Later Moon courts pair an Oracle with a Sentinel");sentinel.Health-=2;float wounded=sentinel.Health;typeof(Enemy).GetField("state",Private).SetValue(oracle,Enum.Parse(typeof(Enemy).GetNestedType("State",BindingFlags.NonPublic),"Notice"));typeof(Enemy).GetField("timer",Private).SetValue(oracle,0f);oracle.enabled=true;g.Player.Warp(court.position+new Vector3(2,.03f,2));yield return new WaitForSeconds(1.7f);check(sentinel.Health>wounded&&sentinel.Health<=sentinel.MaxHealth,"Oracle starfall restores a nearby living Sentinel without exceeding its cap");oracle.enabled=false;}
    foreach(var enemy in g.Enemies)if(!enemy.Boss)Defeat(enemy);yield return new WaitForSeconds(.3f);
    foreach(var key in g.World.Exploration.Finds)if(key.Key){g.Player.Warp(key.transform.position+Vector3.back*1.1f+Vector3.up*.05f);yield return new WaitForSeconds(1.1f);check(key.Claimed,"Gate key recovered before star alignment");}
    foreach(var route in g.Astral.Mechanisms){
     for(int side=0;side<2;side++){
      g.Player.Warp(route.PadPosition(side));yield return new WaitForSeconds(.8f);
      if(route.Shifting){float before=g.Elapsed;g.Pause();yield return new WaitForSeconds(.15f);check(Mathf.Abs(before-g.Elapsed)<.02f&&route.Shifting,"Pause freezes an in-flight route warning");g.Resume();yield return new WaitForSeconds(1.2f);}
      check(route.Side==side&&!route.Shifting,"Proximity pad selects a settled star route");
      if(chapter==21&&route.Index==0){g.Player.Warp(route.transform.position+Vector3.up*.03f);var direction=(route.Courts[side].position-route.transform.position).normalized;var input=Quaternion.Euler(0,-g.CameraRig.Yaw,0)*direction;move(new Vector2(input.x,input.z));yield return new WaitForSeconds(3.8f);move(Vector2.zero);yield return new WaitForSeconds(.2f);check(g.Player.Grounded&&Mathf.Abs(g.Player.transform.position.x-route.Courts[side].position.x)<3,"Aster physically crosses the selected side bridge: "+side+" player="+g.Player.transform.position+" court="+route.Courts[side].position);}
      g.Player.Warp(route.Focuses[side].position+Vector3.back*1.4f);yield return new WaitForSeconds(1.3f);check(route.Attuned[side],"Physical focus channel reconnects court "+side);check(!route.Attune(side),"Connected focuses cannot pay or complete twice");
     }
     Capture(route.transform.position,"chapter-"+chapter+"-routes");
    }
    check(g.Astral.Connected==g.Astral.Mechanisms.Count*2,"Both paths of every mechanism are linked: "+chapter);
    var boss=g.Enemies.Find(e=>e&&e.Kind==31&&e.Health>0);
    if(boss){
     check(!g.GateOpen()&&g.Astral.Seals.Count==3,"Final guardian still seals the completed routes");float hp=boss.Health;boss.Hit(5,-1,false);check(Mathf.Abs(boss.Health-hp)<.01f,"Closed elemental ward blocks direct damage");boss.IgniteRelic();boss.enabled=true;yield return new WaitForSeconds(.9f);check(Mathf.Abs(boss.Health-hp)<.01f,"Closed ward also blocks a charged-hit burn relic");typeof(Enemy).GetField("state",Private).SetValue(boss,Enum.Parse(typeof(Enemy).GetNestedType("State",BindingFlags.NonPublic),"Notice"));typeof(Enemy).GetField("timer",Private).SetValue(boss,4f);boss.enabled=true;g.Player.Warp(boss.transform.position+Vector3.back*8);yield return new WaitForSeconds(.3f);var before=boss.transform.position;yield return new WaitForSeconds(1);check((boss.transform.position-before).sqrMagnitude>.1f&&boss.Grounded,"Final guardian pursues while grounded: delta="+(boss.transform.position-before)+" position="+boss.transform.position+" vertical="+boss.VerticalVelocity+" contact="+(boss.LastContact?boss.LastContact.name:"none"));
     for(int phase=1;phase<=3;phase++){
      g.Player.Power=(phase+1)%3;check(!g.Astral.GroundSeal(phase-1),"Wrong element cannot ground the current ward");g.Player.Power=phase-1;g.Player.Warp(g.Astral.Seals[phase-1].position+Vector3.back*1.4f);yield return new WaitForSeconds(1.3f);check(!boss.AstralWard,"Matching elemental focus exposes phase "+phase);
      if(phase<3){boss.IgniteRelic();while(boss.Health>boss.MaxHealth*(phase==1?.65f:.31f)){boss.Hit(boss.MaxHealth*.04f,-1,false,Vector3.zero,true);yield return new WaitForSeconds(.04f);}yield return new WaitForSeconds(.25f);check(boss.AstralPhase==phase+1&&boss.AstralWard,"Phase transition restores a different elemental ward");float wardHp=boss.Health;yield return new WaitForSeconds(.8f);check(Mathf.Abs(boss.Health-wardHp)<.01f,"Burn cannot carry damage through a restored phase ward");}
     }
     for(int pattern=0;pattern<3;pattern++){typeof(Enemy).GetField("attackCount",Private).SetValue(boss,pattern);typeof(Enemy).GetField("state",Private).SetValue(boss,Enum.Parse(typeof(Enemy).GetNestedType("State",BindingFlags.NonPublic),"Notice"));typeof(Enemy).GetField("timer",Private).SetValue(boss,0f);typeof(Enemy).GetField("astralNext",Private).SetValue(boss,0f);g.Player.Warp(boss.transform.position+Vector3.back*5);yield return new WaitForSeconds(.12f);check(boss.Telegraphing,"Final guardian warns before pattern "+pattern);g.Player.Warp(g.World.Route[g.World.Route.Count-1]+Vector3.left*10);yield return new WaitForSeconds(3);check(boss.Grounded,"Final guardian stays on its deck through pattern "+pattern);}
     check(boss.AstralPatternMask==7,"Final guardian exposes all three attack patterns");Capture(boss.transform.position,"fracture-keeper",6);boss.OpenAstralWard();Defeat(boss);yield return new WaitForSeconds(.3f);
    }
    if(chapter==22){var pulse=g.World.GetComponentInChildren<AstralFracture>();check(pulse,"Astral chapter has a fracture hazard");float offset=pulse.transform.position.z*.03f;g.Elapsed=(Mathf.Floor((g.Elapsed+offset)/7)+1)*7+4.6f-offset;g.Player.Warp(pulse.transform.position+Vector3.right*1.2f);yield return new WaitForSeconds(.1f);check(pulse.Warning,"Fracture warns before erupting");g.Pause();float paused=g.Elapsed;int hurt=g.DamageTaken;yield return new WaitForSeconds(.2f);check(g.Elapsed==paused&&g.DamageTaken==hurt,"Pause freezes the fracture warning without damage");g.Resume();yield return new WaitForSeconds(1.6f);check(g.DamageTaken>hurt,"Aster remaining inside the warning takes fracture damage");Capture(pulse.transform.position,"fracture-pulse",5);}
    int recordCoins=g.Coins,recordGems=g.Gems;g.Player.Warp(g.Astral.Record.position+Vector3.back*1.4f);yield return new WaitForSeconds(1.2f);check(g.Astral.RecordClaimed&&g.Coins==recordCoins+100&&g.Gems==recordGems+4,"Astral record grants its single discovery reward: "+chapter);yield return new WaitForSeconds(1.2f);check(g.Coins==recordCoins+100&&g.Gems==recordGems+4,"Revisiting a record cannot duplicate its reward");check(g.Notice.EndsWith(" / +100 Gold +4 Gems"),"Route hints preserve the current observatory story record: "+chapter);
    check(g.GateOpen(),"Astral gate requires connected mechanisms and final victory: "+chapter);g.Finish();check(g.Save.stars[chapter-1]>=1&&g.Save.unlocked<=25,"Astral clear saves within campaign bounds");
    if(chapter==25){g.ShowEnding();check(g.Screen==GameScreen.Complete&&(bool)typeof(RealmGame).GetField("showEnding",Private).GetValue(g),"Campaign victory opens the epilogue");}
    if(prototype)break;
   }
   g.LoadLevel(21);yield return new WaitForSeconds(.3f);var falling=g.Enemies[0];var y=falling.transform.position.y;falling.Controller.enabled=false;falling.transform.position+=Vector3.right*250;falling.Controller.enabled=true;yield return new WaitForSeconds(1);check(!falling||falling.transform.position.y<y-2,"Astral enemies fall beyond real platform edges");
   g.Save=JsonUtility.FromJson<Progress>(saved);Campaign.Normalize(g.Save);move(Vector2.zero);g.LoadLevel(1);yield return new WaitForSeconds(.2f);
  }
 }
}
